function reminders(){const s=reminderSettings();return `<article class="ka-card"><div class="ka-card__body ka-stack"><div><strong>Hatırlatma Davranışı</strong><div class="ka-muted">Dashboard açıldığında görev, evrak, nöbet, çizelge, kontrol listesi ve sınavlar cihaz verisinden taranır.</div></div><div class="ka-grid"><label class="ka-field"><span class="ka-field__label">Kaç gün kala hatırlatma başlasın?</span><input id="reminderDays" type="number" min="1" max="90" step="1" value="${s.gunSayisi}"></label><label class="ka-field"><span class="ka-field__label">Ertele kaç saat gizlesin?</span><input id="reminderSnoozeHours" type="number" min="1" max="168" step="1" value="${s.erteleSaat}"></label></div><div class="ka-row"><span class="ka-badge">Cihaz-first</span><span class="ka-badge">Firestore arka plan senkronu</span></div></div><div class="ka-card__footer"><button class="ka-btn" type="button" data-reminder-settings-save>Hatırlatma Ayarlarını Kaydet</button></div></article>`}
async function saveReminderSettings(){if(!admin()){toast?.('Bu işlem için yönetici yetkisi gerekir.');return}const days=Number(document.getElementById('reminderDays')?.value),hours=Number(document.getElementById('reminderSnoozeHours')?.value);if(!Number.isInteger(days)||days<1||days>90){toast?.('Hatırlatma gün sayısı 1-90 arasında olmalı.');return}if(!Number.isInteger(hours)||hours<1||hours>168){toast?.('Erteleme süresi 1-168 saat arasında olmalı.');return}const btn=document.querySelector('[data-reminder-settings-save]');if(btn){btn.disabled=true;btn.textContent='Kaydediliyor…'}try{await DeviceData.set('hatirlatmaAyarlari',COL.hatirlatmaAyarlari,'ayarlar',{gunSayisi:days,erteleSaat:hours,guncellenmeTarihi:new Date().toISOString()},{merge:true});toast?.('Hatırlatma ayarları cihazda kaydedildi.');render()}catch(e){toast?.('Hatırlatma ayarları kaydedilemedi: '+(e?.message||e));if(btn){btn.disabled=false;btn.textContent='Hatırlatma Ayarlarını Kaydet'}}}
function moduleEditorRow(m){const locked=m.key==='dashboard'||m.key==='settings';return `<article class="ka-card" data-app-module-row="${esc(m.key)}"><div class="ka-card__body ka-row ka-row--between"><div class="ka-grow"><strong>${esc(m.label)}</strong><div class="ka-muted">${esc(m.key)}${locked?' · her zaman açık':''}</div></div><label class="ka-check"><input type="checkbox" data-app-visible ${m.visible!==false||locked?'checked':''} ${locked?'disabled':''}> Modülü etkin tut</label></div></article>`}
const LAYOUT_ROLES=[['idareci','İdareci'],['ogretmen','Öğretmen']];
let layoutRole='idareci',sozTab='ayet',appDirty=false;
const EXAM_MAX=8,EXAM_HINTS=['LGS','Bursluluk Sınavı','Deneme Sınavı','Dönem Sınavı','TYT','YKS'],SLAYT_MAX=6;
const appSection=(no,title,desc)=>`<div class="ka-row ka-app-section"><span class="ka-setup-no" aria-hidden="true">${no}</span><div class="ka-grow"><strong>${esc(title)}</strong>${desc?`<div class="ka-muted">${esc(desc)}</div>`:''}</div></div>`;
