/* 2 · Kart seçenekleri: şema AppConfig.CARD_OPTIONS'tan gelir (toggle / choice / text) */
function optionControl(card,o,v){
  const id=`${card}.${o.key}`;
  if(o.type==='toggle')return `<label class="ka-check"><input type="checkbox" data-card-opt="${id}" ${v?'checked':''}> ${esc(o.label)}</label>`;
  if(o.type==='choice')return `<div class="ka-field"><span class="ka-field__label">${esc(o.label)}</span><div class="ka-row ka-opt-choices" role="radiogroup" aria-label="${esc(o.label)}">${o.choices.map(([val,lab])=>`<label class="ka-check"><input type="radio" name="opt-${card}-${o.key}" data-card-opt="${id}" value="${esc(val)}" ${String(v)===val?'checked':''}> ${esc(lab)}</label>`).join('')}</div></div>`;
  return `<label class="ka-field"><span class="ka-field__label">${esc(o.label)}</span><input data-card-opt="${id}" value="${esc(v)}" maxlength="${o.max||60}">${o.hint?`<small class="ka-muted">${esc(o.hint)}</small>`:''}</label>`;
}
function cardOptionsEditor(cfg){const cards=window.AppConfig.DASHBOARD_CARDS;return Object.entries(window.AppConfig.CARD_OPTIONS).map(([card,list])=>`<article class="ka-card" data-card-options="${esc(card)}"><div class="ka-card__body ka-stack"><strong>${esc(cards.find(c=>c.key===card)?.label||card)}</strong>${list.map(o=>optionControl(card,o,cfg.cardOptions[card][o.key])).join('')}</div></article>`).join('')}
