const ONUR_PRESETS=[['⭐','Haftanın Öğrencisi'],['🏅','Ayın Öğrencisi'],['🧹','En Temiz Sınıf'],['','Kendi başlığım']];
function onurPersonRow(k={}){return `<div class="ka-grid" data-onur-person><label class="ka-field"><span class="ka-field__label">Ad veya sınıf</span><input data-onur-ad maxlength="60" value="${esc(k.ad||'')}" placeholder="Ayşe Yılmaz ya da 6/C"></label><div class="ka-row"><label class="ka-field ka-grow"><span class="ka-field__label">Açıklama (isteğe bağlı)</span><input data-onur-aciklama maxlength="80" value="${esc(k.aciklama||'')}"></label><button class="ka-btn ka-btn--secondary ka-btn--sm" type="button" data-onur-person-remove aria-label="Adı kaldır">✕</button></div></div>`}
function onurPartRow(b={}){return `<div class="ka-stack ka-onur-part" data-onur-part><div class="ka-row"><label class="ka-field"><span class="ka-field__label">Simge</span><input data-onur-ikon maxlength="4" value="${esc(b.ikon||'')}"></label><label class="ka-field ka-grow"><span class="ka-field__label">Bölüm başlığı</span><input data-onur-baslik maxlength="40" value="${esc(b.baslik||'')}"></label><button class="ka-btn ka-btn--secondary ka-btn--sm" type="button" data-onur-part-remove>Bölümü kaldır</button></div><div class="ka-stack" data-onur-people>${(b.kisiler?.length?b.kisiler:[{}]).map(onurPersonRow).join('')}</div><div class="ka-row"><button class="ka-btn ka-btn--secondary ka-btn--sm" type="button" data-onur-person-add>＋ Ad ekle</button></div></div>`}
const onurEditor=cfg=>`<div class="ka-row ka-opt-choices">${ONUR_PRESETS.map(([i,t])=>`<button class="ka-btn ka-btn--secondary ka-btn--sm" type="button" data-onur-add data-onur-ikon-new="${esc(i)}" data-onur-baslik-new="${i?esc(t):''}">${i?`${i} ${esc(t)}`:'＋ Kendi başlığım'}</button>`).join('')}</div><div class="ka-stack" id="onurEditor">${cfg.onurPanosu.map(onurPartRow).join('')}</div>`;
/* 6 · Slayt resimleri: yüklenen her resim appConfig türünde ayrı 'slayt-N' belgesidir; yükleme/kaldırma hemen kaydedilir */
const slaytRows=()=>arr('appConfig').filter(x=>/^slayt-\d+$/.test(String(x?.id||''))).sort((a,b)=>Number(a.sira||0)-Number(b.sira||0));
const slaytGrid=rows=>rows.length?rows.map((x,i)=>`<figure class="ka-slayt-thumb"><img src="${esc(x.veri)}" alt="${esc(x.ad||`Slayt ${i+1}`)}"><button type="button" data-slayt-remove="${esc(x.id)}" aria-label="Resmi kaldır">✕</button></figure>`).join(''):'<div class="ka-muted ka-slayt-empty">Henüz resim eklenmedi; kart resim ekleyene dek ana sayfada görünmez.</div>';
const slaytEditor=()=>`<div class="ka-slayt-grid" id="slaytGrid">${slaytGrid(slaytRows())}</div><div class="ka-row"><label class="ka-btn ka-btn--secondary ka-btn--sm">＋ Resim ekle<input type="file" accept="image/*" multiple hidden data-slayt-file></label><span class="ka-muted" id="slaytCount">${slaytRows().length} / ${SLAYT_MAX} resim</span></div>`;
async function slaytCompress(file){
  const bmp=await createImageBitmap(file),k=Math.min(1,1280/Math.max(bmp.width,bmp.height)),cv=document.createElement('canvas');
  cv.width=Math.max(1,Math.round(bmp.width*k));cv.height=Math.max(1,Math.round(bmp.height*k));cv.getContext('2d').drawImage(bmp,0,0,cv.width,cv.height);bmp.close?.();
  let out='';for(const q of [.72,.6,.5,.4]){out=cv.toDataURL('image/jpeg',q);if(out.length<=700000)break}
  if(out.length>900000)throw new Error('Resim çok büyük; daha küçük bir resim seçin.');
  return out;
}
function slaytRefresh(){const g=document.getElementById('slaytGrid'),c=document.getElementById('slaytCount');if(g)g.innerHTML=slaytGrid(slaytRows());if(c)c.textContent=`${slaytRows().length} / ${SLAYT_MAX} resim`}
async function slaytAdd(files){
  try{window.PermissionService?.require?.('settings.app.edit','edit')}catch(e){toast?.('Bu işlem için yetkiniz yok.');return}
  const free=SLAYT_MAX-slaytRows().length;if(free<=0){toast?.(`En fazla ${SLAYT_MAX} resim eklenebilir.`);return}
  for(const f of [...files].filter(x=>/^image\//.test(x.type)).slice(0,free)){
    try{const veri=await slaytCompress(f),used=new Set(slaytRows().map(r=>r.id));let n=1;while(used.has(`slayt-${n}`))n++;await DeviceData.set('appConfig',COL.navDuzeni,`slayt-${n}`,{veri,ad:f.name.replace(/\.[^.]+$/,'').slice(0,40),sira:Date.now()},{merge:false})}
    catch(e){toast?.('Resim eklenemedi: '+(e?.message||e))}
    finally{slaytRefresh()}
  }
}
async function slaytRemove(id){try{window.PermissionService?.require?.('settings.app.edit','edit');await DeviceData.remove('appConfig',COL.navDuzeni,id)}catch(e){toast?.('Resim kaldırılamadı: '+(e?.message||e))}finally{slaytRefresh()}}
